'use strict';

// MODULES //

var axis = require( '@stdlib/plot/vega/editor-config/axis' );
var background = require( '@stdlib/plot/vega/editor-config/background' );
var description = require( '@stdlib/plot/vega/editor-config/description' );
var height = require( '@stdlib/plot/vega/editor-config/height' );
var padding = require( '@stdlib/plot/vega/editor-config/padding' );
var title = require( '@stdlib/plot/vega/editor-config/title' );
var width = require( '@stdlib/plot/vega/editor-config/width' );


// MAIN //

/**
* Returns an editor configuration for a visualization.
*
* @returns {Object} configuration
*
* @example
* var o = config();
* // returns {...}
*/
function config() {
	return {
		'axis': axis(),
		'background': background(),
		'description': description(),
		'height': height(),
		'padding': padding(),
		'title': title(),
		'width': width()
	};
}


// EXPORTS //

module.exports = config;
